{"title": "Request Volume", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "Request Volume — Dakikalik Istek Sayisi",
  "data": {
    "url": {
      "index": "otel-metrics-*",
      "body": {
        "size": 0,
        "query": {
          "bool": {
            "filter": [
              {
                "term": {
                  "name.keyword": "http.server.request.duration"
                }
              },
              {
                "range": {
                  "time": {
                    "%timefilter%": true
                  }
                }
              }
            ]
          }
        },
        "aggs": {
          "by_time": {
            "date_histogram": {
              "field": "time",
              "fixed_interval": "1m",
              "min_doc_count": 0
            },
            "aggs": {
              "v": {
                "sum": {
                  "field": "count"
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.by_time.buckets"
    }
  },
  "transform": [
    {
      "calculate": "datum.v.value",
      "as": "value"
    }
  ],
  "mark": {
    "type": "line",
    "point": true,
    "tooltip": true,
    "color": "#1f77b4",
    "interpolate": "monotone"
  },
  "encoding": {
    "x": {
      "field": "key_as_string",
      "type": "temporal",
      "title": "Zaman"
    },
    "y": {
      "field": "value",
      "type": "quantitative",
      "title": "Istek / dk"
    }
  },
  "width": "container",
  "height": "container",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  }
}"}}

{"title": "API Response Time", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "API Response Time — Ortalama Yanit Suresi (ms)",
  "data": {
    "url": {
      "index": "otel-metrics-*",
      "body": {
        "size": 0,
        "query": {
          "bool": {
            "filter": [
              {
                "term": {
                  "name.keyword": "http.server.request.duration"
                }
              },
              {
                "range": {
                  "time": {
                    "%timefilter%": true
                  }
                }
              }
            ]
          }
        },
        "aggs": {
          "by_time": {
            "date_histogram": {
              "field": "time",
              "fixed_interval": "1m",
              "min_doc_count": 0
            },
            "aggs": {
              "s": {
                "sum": {
                  "field": "sum"
                }
              },
              "c": {
                "sum": {
                  "field": "count"
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.by_time.buckets"
    }
  },
  "transform": [
    {
      "calculate": "datum.c.value > 0 ? datum.s.value / datum.c.value * 1000 : 0",
      "as": "value"
    }
  ],
  "mark": {
    "type": "line",
    "point": true,
    "tooltip": true,
    "color": "#2ca02c",
    "interpolate": "monotone"
  },
  "encoding": {
    "x": {
      "field": "key_as_string",
      "type": "temporal",
      "title": "Zaman"
    },
    "y": {
      "field": "value",
      "type": "quantitative",
      "title": "Yanit suresi (ms)"
    }
  },
  "width": "container",
  "height": "container",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  }
}"}}

{"title": "Error Rate", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "Error Rate — Hata Orani (%)",
  "data": {
    "url": {
      "index": "otel-metrics-*",
      "body": {
        "size": 0,
        "query": {
          "bool": {
            "filter": [
              {
                "term": {
                  "name.keyword": "http.server.request.duration"
                }
              },
              {
                "range": {
                  "time": {
                    "%timefilter%": true
                  }
                }
              }
            ]
          }
        },
        "aggs": {
          "by_time": {
            "date_histogram": {
              "field": "time",
              "fixed_interval": "1m",
              "min_doc_count": 0
            },
            "aggs": {
              "total": {
                "sum": {
                  "field": "count"
                }
              },
              "errors": {
                "filter": {
                  "range": {
                    "metric.attributes.http@response@status_code": {
                      "gte": 400
                    }
                  }
                },
                "aggs": {
                  "c": {
                    "sum": {
                      "field": "count"
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.by_time.buckets"
    }
  },
  "transform": [
    {
      "calculate": "datum.total.value > 0 ? datum.errors.c.value / datum.total.value * 100 : 0",
      "as": "value"
    }
  ],
  "mark": {
    "type": "line",
    "point": true,
    "tooltip": true,
    "color": "#d62728",
    "interpolate": "monotone"
  },
  "encoding": {
    "x": {
      "field": "key_as_string",
      "type": "temporal",
      "title": "Zaman"
    },
    "y": {
      "field": "value",
      "type": "quantitative",
      "title": "Hata orani (%)"
    }
  },
  "width": "container",
  "height": "container",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  }
}"}}

{"title": "Service Health", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "Service Health — JVM Heap Kullanimi (MB)",
  "data": {
    "url": {
      "index": "otel-metrics-*",
      "body": {
        "size": 0,
        "query": {
          "bool": {
            "filter": [
              {
                "bool": {
                  "must": [
                    {
                      "term": {
                        "name.keyword": "jvm.memory.used"
                      }
                    },
                    {
                      "term": {
                        "metric.attributes.jvm@memory@type.keyword": "heap"
                      }
                    }
                  ]
                }
              },
              {
                "range": {
                  "time": {
                    "%timefilter%": true
                  }
                }
              }
            ]
          }
        },
        "aggs": {
          "by_time": {
            "date_histogram": {
              "field": "time",
              "fixed_interval": "1m",
              "min_doc_count": 0
            },
            "aggs": {
              "m": {
                "avg": {
                  "field": "value"
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.by_time.buckets"
    }
  },
  "transform": [
    {
      "calculate": "datum.m.value / 1048576",
      "as": "value"
    }
  ],
  "mark": {
    "type": "line",
    "point": true,
    "tooltip": true,
    "color": "#9467bd",
    "interpolate": "monotone"
  },
  "encoding": {
    "x": {
      "field": "key_as_string",
      "type": "temporal",
      "title": "Zaman"
    },
    "y": {
      "field": "value",
      "type": "quantitative",
      "title": "JVM Heap (MB)"
    }
  },
  "width": "container",
  "height": "container",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  }
}"}}
